-- BastionPay 테스트용 데이터. 보안 대시보드·등급·이체 검토 등 기능별 시험 상황을 만들기 위한 파일이다(개발 DB 전용, 운영에는 넣지 않는다).
-- 대상 DB: bastionpay_db (3306). 앱을 한 번 띄워 Flyway 로 테이블을 만든 뒤 실행한다(기본 시드 member.sql 을 따로 넣지 않아도 된다). 여러 번 실행해도 같은 결과가 된다.
-- 가짜 은행의 db/seed/mockbank-test.sql 과 짝이다(이체 기록의 출금 계좌가 그 파일의 "거래내역 많은 통장"). 시각은 실행 시점 기준 상대 시각이다.
-- 모든 계정의 비밀번호: 12345678A!
--
-- 회원
--   locked@test.com     관리자가 수동으로 잠근 계정(로그인 불가, 잠금 해제 시험)
--   review@test.com     "검토가 필요한 이체" 12건 + 환불 2건 → 개요의 검토 이체 10건씩 쪽 나누기 시험
--   volume@test.com     STANDARD, 누적 이체 950만원 → 50만원 이상 이체가 완료되면 VIP 로 자동 승급(기준 1,000만원)
--   inactive@test.com   VIP 인데 마지막 이용이 4개월 전 → 로그인하거나 새벽 배치가 돌면 STANDARD 로 자동 강등
--   overpriv@test.com   허용 목록(ADMIN_ALLOWLIST) 밖의 관리자 → "허용 목록 밖 관리자(과잉권한)"에 표시, 권한 회수 시험
-- 보안 대시보드: 보안 이벤트 약 145건(모든 분류·심각도, 최근 7일에 걸쳐), 인시던트 티켓 7건(열림·종료), 차단 IP 4개, 감사 기록 14건,
--   로그인 실패로 잠긴 계정 1개. 시험용 출발지는 198.18.0.x / 100.64.0.x 대역이다(실제 IP 와 섞이지 않는다).
--
-- 이 파일 하나로 시험 환경이 완성된다: 기본 더미 회원(test·vip·vvip·admin@test.com)도 함께 넣는다(이미 있으면 같은 값으로 갱신한다). 본인이 직접 가입한 계정은 들어 있지 않다.

-- ===== 기본 더미 데이터 (member.sql 와 같은 내용) =====
-- BastionPay 개발용 더미 회원. 팀원 모두 같은 계정으로 맞추기 위한 파일이다. 개발 DB 전용이며 운영에는 넣지 않는다.
-- 대상 DB: bastionpay_db. 여러 번 실행해도 같은 결과가 되도록 이메일 기준으로 갱신한다.
-- 모든 계정의 비밀번호: 12345678A!   (bcrypt 해시만 저장)
-- 역할(role)과 등급(tier)은 별개다. USER/ADMIN 은 권한, STANDARD/VIP/VVIP 는 등급.
ON DUPLICATE KEY UPDATE
    name = VALUES(name), nickname = VALUES(nickname), password_hash = VALUES(password_hash),
    role = VALUES(role), tier = VALUES(tier), status = VALUES(status), updated_at = NOW(6);

-- ===== 테스트용 데이터 =====
ON DUPLICATE KEY UPDATE name = VALUES(name), nickname = VALUES(nickname), password_hash = VALUES(password_hash), role = VALUES(role),
    tier = VALUES(tier), status = VALUES(status), locked_at = VALUES(locked_at), lock_reason = VALUES(lock_reason), last_active_at = VALUES(last_active_at),
    tier_changed_at = VALUES(tier_changed_at), tier_baseline_at = VALUES(tier_baseline_at), updated_at = NOW(6);

-- 이체 기록: review@test.com 은 검토 필요 12건 + 환불 2건, volume@test.com 은 완료 5건(합계 950만원)
ON DUPLICATE KEY UPDATE status = VALUES(status), failure_code = VALUES(failure_code), amount = VALUES(amount), updated_at = VALUES(updated_at), created_at = VALUES(created_at);

-- 보안 이벤트(event_id 가 5eed0000- 로 시작하는 행만 지우고 다시 넣는다)
DELETE FROM audit_log WHERE event_id LIKE '5eed0000-%';
DELETE FROM security_event WHERE event_id LIKE '5eed0000-%';


-- 인시던트 티켓(created_by 가 seed 인 행만 지우고 다시 넣는다). 같은 IP 의 열린 티켓은 하나뿐이다
DELETE FROM incident WHERE created_by = 'seed';

-- 차단된 IP
ON DUPLICATE KEY UPDATE reason = VALUES(reason), blocked_by = VALUES(blocked_by), blocked_at = VALUES(blocked_at);

-- 감사 기록(event_id 5eed0000-…-9xxx). 누가(ADMIN/API/SYSTEM) 무엇을 했는지

-- 로그인 실패로 자동 잠긴 계정 1개(15분 뒤 풀린다. 실행할 때마다 다시 잠근다)
SELECT id, 5, UTC_TIMESTAMP(6) - INTERVAL 1 MINUTE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6) + INTERVAL 15 MINUTE, UTC_TIMESTAMP(6) FROM member WHERE email = 'vvip@test.com'
ON DUPLICATE KEY UPDATE failed_count = 5, locked_at = UTC_TIMESTAMP(6), locked_until = UTC_TIMESTAMP(6) + INTERVAL 15 MINUTE, updated_at = UTC_TIMESTAMP(6);
